import { defineConfig, devices } from "@playwright/test";
import { existsSync } from "node:fs";

if (existsSync(".env")) process.loadEnvFile(".env");
const production = process.env.E2E_PRODUCTION_BUILD === "1";
// E2E_BASE_URL points the suite at an app that is already running (for example a production build on another port).
const external = process.env.E2E_BASE_URL;

export default defineConfig({
  testDir: "./e2e",
  // e2e/*.test.ts are Vitest unit tests, not browser specs.
  testMatch: "**/*.spec.ts",
  use: {
    baseURL: external ?? "http://localhost:3000",
  },
  webServer: external ? undefined : {
    command: production ? "npm start" : "npm run dev",
    port: 3000,
    reuseExistingServer: !production && !process.env.CI,
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
});
// Shared deterministic fixtures for Moneo Playwright e2e (prompt.md §46).
//
// Mocked journeys reuse these fixtures; authenticated specs also exercise real
// Supabase workflows and configured free-provider calls. See e2e/README.md
// for each check's limits and required authentication.
import * as fs from "node:fs";
import type { Sql } from "postgres";

// Removes a spec's disposable user. reset_workspace() (Settings "Reset all data") empties every
// workspace table in dependency order, so cleanup cannot drift behind the schema; the rest removes
// the user itself. The caller removes storage objects first.
export async function deleteDisposableUser(db: Sql, user: string) {
  await db.begin(async tx => {
    await tx`select set_config('request.jwt.claim.sub', ${user}, true)`;
    await tx`select public.reset_workspace()`;
    await tx`delete from public.workspace_settings where workspace_id in (select id from public.workspaces where owner_id = ${user})`;
    await tx`delete from public.categories where workspace_id in (select id from public.workspaces where owner_id = ${user})`;
    await tx`delete from public.workspaces where owner_id = ${user}`;
    await tx`delete from auth.users where id = ${user}`;
  });
}

// Minimal two-row statement. Amounts are exact decimal strings; the app owns
// minor-unit conversion, so fixtures never pre-convert.
export const AUGUST_CSV = [
  "date,description,amount",
  "2026-08-01,Salary Acme,2500.00",
  "2026-08-02,AMZN MKTP DE,-42.99",
  "",
].join("\n");

// Overlapping newer file: repeats one August row (dedup candidate) plus new
// September rows. Used by the gated spec to verify re-import safety.
export const SEPTEMBER_CSV = [
  "date,description,amount",
  "2026-08-02,AMZN MKTP DE,-42.99",
  "2026-09-01,Salary Acme,2500.00",
  "2026-09-03,Spotify,-10.99",
  "",
].join("\n");

// Deterministic stand-in for the AI-proposed column mapping
// (POST /api/imports/inspect without a `mapping` field calls OpenAI in
// production; tests fulfil that request with this payload instead).
const MOCK_MAPPING = {
  accountName: "Checking",
  currencyCode: "EUR",
  dateColumn: "date",
  descriptionColumn: "description",
  amountColumn: "amount",
  dateFormat: "iso",
  amountSign: "signed",
  numericConvention: "decimal-dot",
} as const;

// Canned inspect response shaped exactly like app/api/imports/inspect.
// amountMinor is serialized as a string by the real route.
export function mockInspectResponse(accountName = "Checking") {
  return {
    headers: ["date", "description", "amount"],
    sample: [
      { date: "2026-08-01", description: "Salary Acme", amount: "2500.00" },
      { date: "2026-08-02", description: "AMZN MKTP DE", amount: "-42.99" },
    ],
    mapping: { ...MOCK_MAPPING, accountName },
    preview: {
      accountName,
      currencyCode: "EUR",
      totalRows: 2,
      dateRange: { from: "2026-08-01", to: "2026-08-02" },
      examples: [
        {
          postedOn: "2026-08-01",
          description: "Salary Acme",
          amountMinor: "250000",
          currencyCode: "EUR",
        },
        {
          postedOn: "2026-08-02",
          description: "AMZN MKTP DE",
          amountMinor: "-4299",
          currencyCode: "EUR",
        },
      ],
    },
  };
}

export function mockCompletedImport(
  overrides: Record<string, unknown> = {},
) {
  return {
    id: "import-1",
    filename: "august.csv",
    status: "completed",
    total_rows: 2,
    new_rows: 2,
    matched_rows: 0,
    review_rows: 0,
    rejected_rows: 0,
    error: null,
    created_at: "2026-09-26T00:00:00.000Z",
    ...overrides,
  };
}

export function hasSupabaseEnv(): boolean {
  return Boolean(
    process.env.NEXT_PUBLIC_SUPABASE_URL &&
      process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  );
}

// Full-journey auth uses a pre-authenticated Playwright storageState file
// (there is no sign-in page to drive). The gated spec
// skips unless this file exists; see e2e/README.md §2 for creation steps.
export function e2eStorageStatePath(): string | null {
  const candidate = process.env.E2E_STORAGE_STATE;
  if (candidate && fs.existsSync(candidate)) return candidate;
  const fallback = "e2e/.auth.json";
  return fs.existsSync(fallback) ? fallback : null;
}

export function gatedSkipReason(): string {
  const missing: string[] = [];
  if (!process.env.NEXT_PUBLIC_SUPABASE_URL)
    missing.push("NEXT_PUBLIC_SUPABASE_URL");
  if (!process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY)
    missing.push("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY");
  if (!e2eStorageStatePath())
    missing.push("E2E_STORAGE_STATE (or e2e/.auth.json storageState)");
  return (
    `Skipped: full authenticated Supabase journey needs ${missing.join(", ")}. ` +
    `This is a SKIP, not a pass — see e2e/README.md §2. ` +
    `Credential-free specs (smoke + mocked import journey) still run.`
  );
}
// Signs the persistent QA user in and saves e2e/.auth.json for the authenticated Playwright
// specs, so tests never touch the owner's workspace. The first run creates the user and stores
// its login as E2E_USER_EMAIL / E2E_USER_PASSWORD in the git-ignored .env.
// Sign in (E2E_BASE_URL defaults to http://localhost:3000):  node --env-file=.env scripts/e2e-auth.mjs
// Empty its workspace (specs expect one):      node --env-file=.env scripts/e2e-auth.mjs --reset
import { randomBytes } from "node:crypto";
import { appendFileSync, writeFileSync } from "node:fs";
import { createClient } from "@supabase/supabase-js";
import { createServerClient } from "@supabase/ssr";
import postgres from "postgres";

const statePath = "e2e/.auth.json";
let email = process.env.E2E_USER_EMAIL, password = process.env.E2E_USER_PASSWORD;

if (process.argv.includes("--reset")) {
  if (!email) throw new Error("No E2E_USER_EMAIL in .env; run without --reset first");
  const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
  await db.begin(async tx => {
    const [user] = await tx`select id, raw_user_meta_data->>'qa_test' as qa from auth.users where email=${email}`;
    if (user?.qa !== "e2e-auth") throw new Error("Refusing to reset a user not created by this script");
    const workspaces = (await tx`select id from public.workspaces where owner_id=${user.id}`).map(row => row.id);
    // Audit tables reference each other, so skip FK triggers for this one owned sweep.
    // ponytail: column-name sweep; extend the list if a new owner column appears.
    await tx`set local session_replication_role = replica`;
    const columns = await tx`select table_name, column_name from information_schema.columns join information_schema.tables using (table_schema, table_name)
      where table_schema='public' and table_type='BASE TABLE' and table_name <> 'workspaces'
      and column_name in ('workspace_id','actor_id','user_id','created_by')`;
    for (const { table_name, column_name } of columns)
      await tx.unsafe(`delete from public."${table_name}" where "${column_name}"::text = any($1::text[])`, [[user.id, ...workspaces]]);
    // Same starting categories a new signup gets from seed_default_categories().
    await tx`insert into public.categories(workspace_id,name) select w,n from unnest(${workspaces}::uuid[]) w cross join unnest(public.default_category_names()) n`;
  });
  await db.end();
  console.log("Emptied the QA user's workspace");
  process.exit(0);
}

if (!email) {
  email = `qa-${Date.now()}@example.test`;
  password = randomBytes(24).toString("base64url");
  const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });
  const { error } = await admin.auth.admin.createUser({ email, password, email_confirm: true, user_metadata: { qa_test: "e2e-auth" } });
  if (error) throw error;
  appendFileSync(".env", `\nE2E_USER_EMAIL=${email}\nE2E_USER_PASSWORD=${password}\n`);
}

// There is no sign-in page (the app signs its owner in automatically), so sign the QA user in
// here and save its session cookie: with it, the app serves the QA user's workspace instead.
const cookies = [];
const auth = createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY, {
  cookies: { getAll: () => [], setAll: list => cookies.push(...list) },
});
const { error } = await auth.auth.signInWithPassword({ email, password });
if (error) throw error;
const { hostname } = new URL(process.env.E2E_BASE_URL ?? "http://localhost:3000");
const expires = Math.floor(Date.now() / 1000) + 400 * 86_400;
writeFileSync(statePath, JSON.stringify({ cookies: cookies.map(({ name, value }) => ({ name, value, domain: hostname, path: "/", expires, httpOnly: false, secure: false, sameSite: "Lax" })), origins: [] }, null, 2));
console.log(`Saved ${statePath} for ${email}`);
# Browser tests

Playwright tests run against the app on http://localhost:3000. The config starts it (`npm run dev`, or the production build with `E2E_PRODUCTION_BUILD=1`) unless a server is already running there.

## Setup

1. Start the backend: `npm run setup`.
2. Create the QA user and save its session: `node --env-file=.env scripts/e2e-auth.mjs`. Its login is stored in `.env` as `E2E_USER_EMAIL`/`E2E_USER_PASSWORD`, and its session in `e2e/.auth.json` (or set `E2E_STORAGE_STATE`).
3. Before a full run, empty its workspace: `node --env-file=.env scripts/e2e-auth.mjs --reset`. Never delete the user.

Tests never use the owner's workspace: a saved QA session takes the place of the owner's automatic sign-in.

## Running

```sh
npm run test:e2e -- --workers=1
```

Use one worker: several specs change the same QA workspace and its preferences. Stop a running server on port 3000 before `npm run build`, so the two don't write `.next` at the same time.

## Kinds of specs

- `*.smoke.spec.ts` and `*.mocked.spec.ts` need no saved session; mocked specs stub API responses to check UI contracts.
- `*.gated.spec.ts` need the backend. Most use the QA session; others create disposable users with the service key, sign them in by session cookie, and remove them in `finally`. If interrupted, their IDs are left in ignored `.qa/` files for cleanup.
- `core-journey.gated.spec.ts` calls the real AI provider, so it costs money: run it only when you mean to.
- `review-runtime.config.ts` and `review-investigation.config.ts` run the real Workflow engine against local synthetic database and model servers (ports 3040/3041), including a server restart mid-review: `npx playwright test --config e2e/review-runtime.config.ts`.

A skipped spec is not a pass: it means a prerequisite (backend, QA session, service key) is missing.

## Acceptance

`npm run acceptance:fast` runs unit tests, lint and the build. `npm run acceptance:required` then runs the SQL regressions, live database checks and the browser suite on that build with one worker. Results go to an ignored `.qa/acceptance-*` folder; logs there may contain workspace data, so keep them out of the repo.

## Scalable

`scalable-trading.gated.spec.ts` drives chat against a local stand-in for Scalable's MCP server (`e2e/mocks/scalable-mcp.mjs`, made-up data) with the real AI model. Start the app with `SCALABLE_MCP_ORIGIN=http://127.0.0.1:3043` and run the spec with the same variable; the spec starts the stand-in, adds a Scalable connection to the QA workspace and removes it afterwards. It checks that an order is previewed on a card and sent only when the card is tapped, once, and that read-only access is told it can't trade.

